  input rst_IBUF;
  input clk_IBUF_BUFG;

  wire clk_IBUF_BUFG;
  wire rst_IBUF;
  wire rst_meta;
  wire rst_sync;

  FDRE #(
    .INIT(1'b0)) 
    rst_meta_reg
       (.C(clk_IBUF_BUFG),
        .CE(1'b1),
        .D(rst_IBUF),
        .Q(rst_meta),
        .R(1'b0));
  FDRE #(
    .INIT(1'b0)) 
    rst_out_reg
       (.C(clk_IBUF_BUFG),
        .CE(1'b1),
        .D(rst_meta),
        .Q(rst_sync),
        .R(1'b0));
endmodule
